import { FormEvent, useEffect, useMemo, useState } from "react";
import type { User } from "@supabase/supabase-js";
import {
  AlertTriangle, ArrowRight, Building2, Check, CheckCircle2, ClipboardList,
  Clock3, Edit3, History, LoaderCircle, MailPlus, Plus, RefreshCw, Search,
  Settings2, ShieldCheck, Trash2, Users, UserRoundCheck, UserRoundX, X,
} from "lucide-react";
import { supabase } from "@/lib/supabase";

type Tab = "resumo" | "usuarios" | "acessos" | "modulos" | "atribuicoes" | "convites" | "unidades" | "auditoria";
type UserRow = {
  user_id: number; uuid?: string | null; name?: string | null; email: string; ativo?: boolean;
  primeiro_acesso?: boolean; convite_enviado_em?: string | null; convite_aceito_em?: string | null;
  perfil_legacy?: string | null; assignments?: Assignment[];
};
type Assignment = {
  id?: string; role_id?: string; role_label?: string; org_unit_id?: string; org_unit_name?: string;
  org_unit_code?: string; module_ids?: string[]; active?: boolean; valid_from?: string | null; valid_until?: string | null;
};
type ScopeRow = { assignment_id: string; scope_type?: string | null; scope_key?: string | null };
type Unit = { id: string; parent_id?: string | null; code: string; name: string; unit_type: string; description?: string; sort_order?: number; is_active: boolean };
type Role = { id: string; label: string; description?: string; is_active: boolean };
type Invite = { id: string; invitee_name: string; invitee_email: string; requested_by_name?: string; requested_by_email?: string; module_id?: string; module_label?: string; role_id?: string; role_label?: string; org_unit_id?: string; org_unit_name?: string; status?: string; requested_at: string; invitation_sent_at?: string | null };
type AuditRow = { id: number | string; action?: string; operacao?: string; created_at?: string; occurred_at?: string; actor_name?: string; actor_email?: string; target_name?: string; target_email?: string; details?: Record<string, unknown>; entidade?: string; ator_nome?: string; ocorrido_em?: string };
type ModuleRow = { id: string; label: string; description?: string; icon_name?: string; is_ready?: boolean; status_label?: string; sort_order?: number };
type AssignmentView = { user: UserRow; assignment: Assignment; role?: Role; unit?: Unit; modules: ModuleRow[]; scopes: ScopeRow[]; issues: string[]; effective: boolean; status: "Vigente" | "Programada" | "Expirada" | "Inativa" | "Inconsistente" };
type AccessRow = { user: UserRow; assignment: Assignment; role?: Role; unit?: Unit; module: ModuleRow; scopes: ScopeRow[] };
type AssignmentForm = { id: string; user_id: string; org_unit_id: string; role_id: string; module_ids: string[]; active: boolean; valid_from: string; valid_until: string; justification: string };
type ModuleForm = { id: string; label: string; description: string; icon_name: string; status_label: string; sort_order: string; is_ready: boolean };
type ScopeForm = { assignment_id: string; scope_type: string; scope_key: string };

function rows<T>(value: unknown): T[] { return Array.isArray(value) ? value as T[] : value ? [value as T] : []; }
function one<T>(value: unknown): T | null { return Array.isArray(value) ? (value[0] as T | undefined) || null : (value as T | null); }
function errorText(error: { message?: string } | null) { return error?.message || "Não foi possível carregar os dados de Governança."; }
function dateLabel(value?: string | null) { return value ? new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "short" }).format(new Date(value)) : "—"; }
function dateOnlyLabel(value?: string | null) { return value ? new Intl.DateTimeFormat("pt-BR", { dateStyle: "short" }).format(new Date(`${value}T00:00:00`)) : "—"; }
function moduleIds(value: unknown) { return Array.isArray(value) ? value.map(String).filter(Boolean) : []; }
function todayISO() { return new Date().toISOString().slice(0, 10); }
function dateStart(value?: string | null) { return value ? new Date(`${value}T00:00:00`) : null; }
function scopeLabel(scope: ScopeRow) { return `${scope.scope_type || "Escopo"}${scope.scope_key ? ` · ${scope.scope_key}` : ""}`; }
function validityLabel(assignment: Assignment) { return `${assignment.valid_from ? `De ${dateOnlyLabel(assignment.valid_from)}` : "Início não informado"}${assignment.valid_until ? ` até ${dateOnlyLabel(assignment.valid_until)}` : " · sem fim"}`; }
function assignmentStatus(assignment: Assignment, issues: string[]): AssignmentView["status"] {
  const from = dateStart(assignment.valid_from); const until = dateStart(assignment.valid_until); const today = new Date(`${todayISO()}T00:00:00`);
  if (assignment.active !== true) return "Inativa"; if (from && from > today) return "Programada"; if (until && until < today) return "Expirada"; return issues.length ? "Inconsistente" : "Vigente";
}
function statusClass(status: AssignmentView["status"]) { return status === "Vigente" ? "governance-pill--green" : status === "Inconsistente" ? "governance-pill--red" : status === "Programada" ? "governance-pill--blue" : "governance-pill--amber"; }
function actionLabel(value?: string | null) { const labels: Record<string, string> = { GRANT: "Concessão de acesso", GRANT_ACCESS: "Concessão de acesso", REVOKE: "Revogação de acesso", REVOKE_ACCESS: "Revogação de acesso", ASSIGN: "Atribuição criada", UPDATE_ASSIGNMENT: "Atribuição alterada", ROLE_CHANGE: "Alteração de papel", UNIT_CHANGE: "Alteração de unidade", SCOPE_CHANGE: "Alteração de escopo", VALIDITY_CHANGE: "Alteração de vigência", USER_ACTIVATED: "Usuário ativado", USER_DEACTIVATED: "Usuário desativado", ASSIGNMENT_SAVE: "Atribuição salva" }; return (value && (labels[value] || labels[value.toUpperCase()])) || value || "Evento de Governança"; }
function auditDetails(details?: Record<string, unknown>) { if (!details) return "Detalhes não informados"; const labels: Array<[string, string]> = [["module_label", "módulo"], ["role_label", "papel"], ["org_unit_name", "unidade"], ["scope_type", "tipo de escopo"], ["scope_key", "escopo"], ["valid_from", "início"], ["valid_until", "fim"], ["justification", "justificativa"]]; const values = labels.map(([key, label]) => details[key] !== undefined && details[key] !== null && details[key] !== "" ? `${label}: ${String(details[key])}` : "").filter(Boolean); return values.length ? values.join(" · ") : "Alteração registrada no contexto institucional"; }
function emptyAssignment(): AssignmentForm { return { id: "", user_id: "", org_unit_id: "", role_id: "", module_ids: [], active: true, valid_from: todayISO(), valid_until: "", justification: "" }; }
function emptyModule(): ModuleForm { return { id: "", label: "", description: "", icon_name: "ShieldCheck", status_label: "Disponível", sort_order: "0", is_ready: true }; }

export function GovernanceModule({ user, onBack, onLogout }: { user: User; onBack: () => void; onLogout: () => void }) {
  const [tab, setTab] = useState<Tab>("resumo");
  const [users, setUsers] = useState<UserRow[]>([]); const [units, setUnits] = useState<Unit[]>([]); const [roles, setRoles] = useState<Role[]>([]); const [invites, setInvites] = useState<Invite[]>([]); const [audits, setAudits] = useState<AuditRow[]>([]); const [modules, setModules] = useState<ModuleRow[]>([]); const [scopes, setScopes] = useState<ScopeRow[]>([]);
  const [context, setContext] = useState<Record<string, unknown> | null>(null); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [notice, setNotice] = useState(""); const [search, setSearch] = useState(""); const [auditSearch, setAuditSearch] = useState(""); const [selectedModule, setSelectedModule] = useState(""); const [selectedAssignmentId, setSelectedAssignmentId] = useState("");
  const [inviteForm, setInviteForm] = useState({ nome: "", email: "", perfil_municipal: "ADMINISTRATIVO", role_id: "", org_unit_id: "", module_ids: [] as string[] }); const [unitForm, setUnitForm] = useState({ id: "", parent_id: "", code: "", name: "", unit_type: "SECRETARIA", description: "", sort_order: "0", is_active: true });
  const [assignmentForm, setAssignmentForm] = useState<AssignmentForm>(emptyAssignment); const [moduleForm, setModuleForm] = useState<ModuleForm>(emptyModule); const [scopeForm, setScopeForm] = useState<ScopeForm>({ assignment_id: "", scope_type: "ORG_UNIT", scope_key: "" });

  const activeUsers = useMemo(() => users.filter((item) => item.ativo !== false), [users]); const filteredUsers = useMemo(() => users.filter((item) => `${item.name || ""} ${item.email} ${item.perfil_legacy || ""}`.toLowerCase().includes(search.toLowerCase().trim())), [users, search]); const pendingInvites = useMemo(() => invites.filter((item) => !item.status || ["PENDING", "PENDENTE"].includes(item.status)), [invites]); const moduleMap = useMemo(() => new Map(modules.map((item) => [item.id, item])), [modules]); const roleMap = useMemo(() => new Map(roles.map((item) => [item.id, item])), [roles]); const unitMap = useMemo(() => new Map(units.map((item) => [item.id, item])), [units]);
  const scopesByAssignment = useMemo(() => { const map = new Map<string, ScopeRow[]>(); scopes.forEach((scope) => map.set(scope.assignment_id, [...(map.get(scope.assignment_id) || []), scope])); return map; }, [scopes]);
  const assignmentViews = useMemo<AssignmentView[]>(() => users.flatMap((currentUser) => (currentUser.assignments || []).map((assignment) => { const role = assignment.role_id ? roleMap.get(assignment.role_id) : undefined; const unit = assignment.org_unit_id ? unitMap.get(assignment.org_unit_id) : undefined; const assignedModuleIds = moduleIds(assignment.module_ids); const assignedModules = assignedModuleIds.map((id) => moduleMap.get(id)).filter((item): item is ModuleRow => Boolean(item)); const assignmentScopes = assignment.id ? scopesByAssignment.get(assignment.id) || [] : []; const issues: string[] = []; if (currentUser.ativo === false) issues.push("Usuário inativo"); if (assignment.active !== true) issues.push("Atribuição inativa"); if (dateStart(assignment.valid_from) && dateStart(assignment.valid_from)! > new Date(`${todayISO()}T00:00:00`)) issues.push(`Início de vigência em ${dateOnlyLabel(assignment.valid_from)}`); if (dateStart(assignment.valid_until) && dateStart(assignment.valid_until)! < new Date(`${todayISO()}T00:00:00`)) issues.push(`Vigência encerrada em ${dateOnlyLabel(assignment.valid_until)}`); if (!role || !role.is_active) issues.push("Papel inexistente ou inativo"); if (!unit || !unit.is_active) issues.push("Unidade inexistente ou inativa"); if (!assignedModuleIds.length) issues.push("Atribuição sem módulos"); if (assignedModuleIds.some((id) => !moduleMap.has(id))) issues.push("Módulo não encontrado"); if (assignedModules.some((item) => item.is_ready === false)) issues.push("Módulo indisponível para uso"); return { user: currentUser, assignment, role, unit, modules: assignedModules, scopes: assignmentScopes, issues, effective: issues.length === 0, status: assignmentStatus(assignment, issues) }; })), [users, moduleMap, roleMap, unitMap, scopesByAssignment]);
  const effectiveAccessRows = useMemo<AccessRow[]>(() => assignmentViews.flatMap((view) => view.effective ? view.modules.map((module) => ({ user: view.user, assignment: view.assignment, role: view.role, unit: view.unit, module, scopes: view.scopes })) : []), [assignmentViews]); const filteredAccessRows = useMemo(() => selectedModule ? effectiveAccessRows.filter((item) => item.module.id === selectedModule) : effectiveAccessRows, [effectiveAccessRows, selectedModule]); const selectedAssignment = assignmentViews.find((view) => view.assignment.id === selectedAssignmentId);
  const unitImpacts = useMemo(() => { const map = new Map<string, { assignments: number; activeAssignments: number; modules: Set<string> }>(); assignmentViews.forEach((view) => { if (!view.assignment.org_unit_id) return; const impact = map.get(view.assignment.org_unit_id) || { assignments: 0, activeAssignments: 0, modules: new Set<string>() }; impact.assignments += 1; if (view.effective) impact.activeAssignments += 1; moduleIds(view.assignment.module_ids).forEach((moduleId) => impact.modules.add(moduleId)); map.set(view.assignment.org_unit_id, impact); }); return map; }, [assignmentViews]); const currentUnitImpact = unitForm.id ? unitImpacts.get(unitForm.id) : undefined;
  const summary = { users: activeUsers.length, units: units.filter((item) => item.is_active).length, invites: pendingInvites.length, audit: audits.length, usersWithoutAssignment: activeUsers.filter((item) => !assignmentViews.some((view) => view.user.user_id === item.user_id && view.effective)).length, assignmentsWithoutModules: assignmentViews.filter((view) => !moduleIds(view.assignment.module_ids).length).length, invalidAssignments: assignmentViews.filter((view) => view.issues.some((issue) => !issue.includes("Atribuição sem módulos"))).length, validityAlerts: assignmentViews.filter((view) => ["Programada", "Expirada", "Inativa"].includes(view.status)).length };
  const currentModule = modules.find((item) => item.id === selectedModule);

  async function loadAll() { setLoading(true); setError(""); const [contextResult, usersResult, unitsResult, rolesResult, invitesResult, auditResult, modulesResult, scopesResult] = await Promise.all([supabase.rpc("municipal_governance_get_my_context"), supabase.rpc("municipal_governance_list_users_v2"), supabase.rpc("municipal_governance_list_org_units"), supabase.rpc("municipal_governance_list_roles"), supabase.rpc("municipal_governance_list_pending_invite_requests"), supabase.rpc("municipal_governance_list_audit", { p_search: auditSearch.trim() || null }), supabase.from("municipal_modules").select("id,label,description,icon_name,is_ready,status_label,sort_order").order("sort_order").limit(200), supabase.from("municipal_assignment_scopes").select("assignment_id,scope_type,scope_key").limit(2000)]); const firstError = [contextResult, usersResult, unitsResult, rolesResult, invitesResult, auditResult, modulesResult, scopesResult].find((result) => result.error); if (firstError?.error) setError(errorText(firstError.error)); setContext(one<Record<string, unknown>>(contextResult.data)); setUsers(rows<UserRow>(usersResult.data)); setUnits(rows<Unit>(unitsResult.data)); setRoles(rows<Role>(rolesResult.data)); setInvites(rows<Invite>(invitesResult.data)); setAudits(rows<AuditRow>(auditResult.data)); setModules((modulesResult.data || []) as ModuleRow[]); setScopes((scopesResult.data || []) as ScopeRow[]); if (!selectedModule && modulesResult.data?.[0]) setSelectedModule(modulesResult.data[0].id); setLoading(false); }
  useEffect(() => { void loadAll(); }, [user.id, auditSearch]);
  async function run(operation: () => PromiseLike<{ error: { message?: string } | null }>, success: string) { setBusy(true); setError(""); const result = await operation(); if (result.error) setError(errorText(result.error)); else { setNotice(success); await loadAll(); } setBusy(false); }
  function confirmAction(message: string) { return window.confirm(message); }
  function openAssignment(assignment?: Assignment, targetUser?: UserRow) { setAssignmentForm(assignment ? { id: assignment.id || "", user_id: String(targetUser?.user_id || ""), org_unit_id: assignment.org_unit_id || "", role_id: assignment.role_id || "", module_ids: moduleIds(assignment.module_ids), active: assignment.active !== false, valid_from: assignment.valid_from || todayISO(), valid_until: assignment.valid_until || "", justification: "" } : { ...emptyAssignment(), user_id: targetUser ? String(targetUser.user_id) : "" }); setSelectedAssignmentId(assignment?.id || ""); setTab("atribuicoes"); }
  async function toggleUser(item: UserRow) { const nextActive = item.ativo === false; if (!confirmAction(`${nextActive ? "Reativar" : "Desativar"} o usuário ${item.name || item.email}? Isso pode alterar todos os acessos efetivos associados.`)) return; await run(() => supabase.rpc("municipal_governance_set_user_active", { p_user_id: item.user_id, p_active: nextActive }), nextActive ? "Usuário reativado." : "Usuário desativado."); }
  async function reviewInvite(item: Invite, decision: "approve" | "reject") { if (!confirmAction(`${decision === "approve" ? "Aprovar" : "Rejeitar"} o convite de ${item.invitee_name}?`)) return; await run(() => supabase.rpc("municipal_governance_review_invite_request", { p_request_id: item.id, p_decision: decision }), decision === "approve" ? "Convite aprovado." : "Convite rejeitado."); }
  async function submitInvite(event: FormEvent) { event.preventDefault(); if (!inviteForm.nome || !inviteForm.email || !inviteForm.role_id || !inviteForm.org_unit_id || !inviteForm.module_ids.length) { setError("Informe nome, e-mail, papel, unidade e ao menos um módulo para a atribuição."); return; } setBusy(true); setError(""); const result = await supabase.functions.invoke("invite-municipal-user", { body: { nome: inviteForm.nome, email: inviteForm.email, perfil_municipal: inviteForm.perfil_municipal, role_id: inviteForm.role_id, org_unit_id: inviteForm.org_unit_id, assignment_module_ids: inviteForm.module_ids, secretariat_ids: [], module_ids: inviteForm.module_ids } }); if (result.error) setError(errorText(result.error)); else { setNotice("Convite enviado com atribuição organizacional registrada."); setInviteForm({ nome: "", email: "", perfil_municipal: "ADMINISTRATIVO", role_id: "", org_unit_id: "", module_ids: [] }); await loadAll(); } setBusy(false); }
  async function saveAssignment(event: FormEvent) { event.preventDefault(); if (!assignmentForm.user_id || !assignmentForm.role_id || !assignmentForm.org_unit_id || !assignmentForm.module_ids.length || !assignmentForm.valid_from) { setError("Informe usuário, papel, unidade, módulos e início da vigência."); return; } if (assignmentForm.valid_until && assignmentForm.valid_until < assignmentForm.valid_from) { setError("A data final não pode ser anterior ao início da vigência."); return; } const previous = assignmentForm.id ? assignmentViews.find((view) => view.assignment.id === assignmentForm.id) : undefined; const highImpact = !previous || Boolean(previous && (previous.assignment.role_id !== assignmentForm.role_id || previous.assignment.org_unit_id !== assignmentForm.org_unit_id || JSON.stringify(moduleIds(previous.assignment.module_ids).sort()) !== JSON.stringify([...assignmentForm.module_ids].sort()) || previous.assignment.valid_from !== assignmentForm.valid_from || (previous.assignment.valid_until || "") !== assignmentForm.valid_until || previous.assignment.active !== assignmentForm.active)); if (highImpact && !assignmentForm.justification.trim()) { setError("Informe uma justificativa para criar ou alterar uma atribuição de alto impacto."); return; } if (highImpact && !confirmAction(`${previous ? "Esta alteração" : "Esta nova atribuição"} pode conceder, ampliar ou interromper acessos efetivos. Usuário, papel, unidade, módulos e vigência serão registrados na auditoria. Continuar?`)) return; setBusy(true); setError(""); const validation = await supabase.rpc("municipal_governance_validate_assignment", { p_role_id: assignmentForm.role_id, p_module_ids: assignmentForm.module_ids }); if (validation.error) { setError(errorText(validation.error)); setBusy(false); return; } const result = await supabase.rpc("municipal_governance_save_assignment", { p_assignment_id: assignmentForm.id || null, p_user_id: Number(assignmentForm.user_id), p_org_unit_id: assignmentForm.org_unit_id, p_role_id: assignmentForm.role_id, p_module_ids: assignmentForm.module_ids, p_active: assignmentForm.active, p_valid_from: assignmentForm.valid_from || null, p_valid_until: assignmentForm.valid_until || null, p_justification: assignmentForm.justification.trim() || null }); if (result.error) setError(errorText(result.error)); else { setNotice(assignmentForm.id ? "Atribuição atualizada." : "Atribuição criada."); setAssignmentForm(emptyAssignment()); setSelectedAssignmentId(""); await loadAll(); } setBusy(false); }
  async function endAssignment(view: AssignmentView) { if (!view.assignment.id || !confirmAction(`Encerrar a atribuição de ${view.user.name || view.user.email}? O acesso efetivo será interrompido, mas o histórico será preservado.`)) return; await run(() => supabase.rpc("municipal_governance_delete_assignment", { p_assignment_id: view.assignment.id }), "Atribuição encerrada e removida do acesso efetivo."); setSelectedAssignmentId(""); }
  async function saveModule(event: FormEvent) { event.preventDefault(); if (!moduleForm.id.trim() || !moduleForm.label.trim()) { setError("Informe identificador e nome do módulo."); return; } const impact = effectiveAccessRows.filter((item) => item.module.id === moduleForm.id).length; if (!moduleForm.is_ready && impact && !confirmAction(`Este módulo possui ${impact} acesso(s) efetivo(s). Marcá-lo como indisponível interromperá esses acessos. Continuar?`)) return; await run(() => supabase.rpc("municipal_governance_save_module", { p_id: moduleForm.id.trim(), p_label: moduleForm.label.trim(), p_description: moduleForm.description.trim() || null, p_icon_name: moduleForm.icon_name.trim() || null, p_status_label: moduleForm.status_label.trim() || null, p_sort_order: Number(moduleForm.sort_order) || 0, p_is_ready: moduleForm.is_ready }), moduleForm.id ? "Módulo salvo." : "Módulo criado."); setModuleForm(emptyModule()); }
  async function saveScope(event: FormEvent) { event.preventDefault(); if (!scopeForm.assignment_id || !scopeForm.scope_type.trim() || !scopeForm.scope_key.trim()) { setError("Informe atribuição, tipo e chave do escopo."); return; } if (!confirmAction(`Adicionar o escopo ${scopeForm.scope_type} · ${scopeForm.scope_key}? Isso pode ampliar ou restringir o acesso efetivo da atribuição.`)) return; await run(() => supabase.from("municipal_assignment_scopes").upsert({ assignment_id: scopeForm.assignment_id, scope_type: scopeForm.scope_type.trim(), scope_key: scopeForm.scope_key.trim() }, { onConflict: "assignment_id,scope_type,scope_key" }), "Escopo salvo."); }
  async function deleteScope(scope: ScopeRow) { if (!confirmAction(`Remover o escopo ${scopeLabel(scope)}? O acesso da atribuição poderá ficar sem abrangência.`)) return; await run(() => supabase.from("municipal_assignment_scopes").delete().eq("assignment_id", scope.assignment_id).eq("scope_type", scope.scope_type || "").eq("scope_key", scope.scope_key || ""), "Escopo removido."); }
  async function submitUnit(event: FormEvent) { event.preventDefault(); if (!unitForm.code || !unitForm.name) { setError("Informe código e nome da unidade."); return; } if (unitForm.id && !unitForm.is_active && currentUnitImpact?.activeAssignments && !confirmAction(`Esta unidade possui ${currentUnitImpact.activeAssignments} atribuição(ões) com acesso efetivo. Continuar?`)) return; await run(() => supabase.rpc("municipal_governance_save_org_unit", { p_id: unitForm.id || null, p_parent_id: unitForm.parent_id || null, p_code: unitForm.code, p_name: unitForm.name, p_unit_type: unitForm.unit_type, p_description: unitForm.description, p_sort_order: Number(unitForm.sort_order) || 0, p_is_active: unitForm.is_active }), unitForm.id ? "Unidade atualizada." : "Unidade criada."); setUnitForm({ id: "", parent_id: "", code: "", name: "", unit_type: "SECRETARIA", description: "", sort_order: "0", is_active: true }); }
  const contextName = String(context?.municipio_nome || context?.municipality_name || "Pitangueiras, Paraná"); const resetUnitForm = () => setUnitForm({ id: "", parent_id: "", code: "", name: "", unit_type: "SECRETARIA", description: "", sort_order: "0", is_active: true });

  return <div className="dashboard-shell governance-shell"><header className="app-header"><button className="header-back-button" type="button" onClick={onBack}><ArrowRight size={16} className="header-back-icon" /> Voltar aos módulos</button><div className="user-menu"><div className="user-copy"><strong>{user.user_metadata?.full_name || user.user_metadata?.name || user.email?.split("@")[0] || "Usuário"}</strong><span>{user.email}</span></div><div className="user-avatar user-avatar--initials">{(user.email || "U").slice(0, 2).toUpperCase()}</div><button className="user-menu-button" type="button" aria-label="Sair da conta" onClick={onLogout}><ArrowRight size={16} /></button></div></header>
    <main className="governance-main"><div className="governance-kicker"><span><ShieldCheck size={14} /> Núcleo transversal</span><span className="governance-secure"><i /> RLS e RPCs protegidas</span></div><div className="governance-heading"><div><p className="eyebrow">MatrixIA / controle institucional</p><h1>Governança</h1><p>Usuários, atribuições organizacionais, módulos, convites, unidades e auditoria em uma visão única.</p></div><button className="governance-refresh" type="button" onClick={() => void loadAll()} disabled={loading}><RefreshCw size={14} className={loading ? "governance-spin" : ""} /> Atualizar</button></div><div className="governance-context"><span><Building2 size={15} /> <b>{contextName}</b></span><span>Identidade autenticada · autorização efetiva derivada de atribuições</span></div>{notice && <div className="governance-notice governance-notice--ok"><CheckCircle2 size={16} /> {notice}<button type="button" onClick={() => setNotice("")}><X size={14} /></button></div>}{error && <div className="governance-notice governance-notice--error"><AlertTriangle size={16} /> {error}<button type="button" onClick={() => setError("")}><X size={14} /></button></div>}<div className="governance-metrics"><Metric icon={Users} value={summary.users} label="Usuários ativos" tone="blue" /><Metric icon={Building2} value={summary.units} label="Unidades ativas" tone="green" /><Metric icon={Clock3} value={summary.invites} label="Convites pendentes" tone="amber" /><Metric icon={History} value={summary.audit} label="Eventos carregados" tone="purple" /></div>
      <nav className="governance-tabs" aria-label="Seções de Governança">{([ ["resumo", "Resumo", ClipboardList], ["usuarios", "Usuários", Users], ["acessos", "Acessos", ShieldCheck], ["modulos", "Módulos", Settings2], ["atribuicoes", "Atribuições", Edit3], ["convites", "Convites", MailPlus], ["unidades", "Unidades", Building2], ["auditoria", "Auditoria", History] ] as const).map(([key, label, Icon]) => <button type="button" className={tab === key ? "is-active" : ""} onClick={() => { setTab(key); setSearch(""); }} key={key}><Icon size={16} /> {label}</button>)}</nav>
      {loading ? <div className="governance-empty"><LoaderCircle size={24} className="governance-spin" /> Carregando Governança pelo Supabase…</div> : <section className="governance-panel">
        {tab === "resumo" && <SummaryPanel users={users} units={units} invites={pendingInvites} audits={audits} assignmentViews={assignmentViews} summary={summary} onTab={setTab} />}
        {tab === "usuarios" && <UserDirectoryPanel users={filteredUsers} assignmentViews={assignmentViews} search={search} setSearch={setSearch} busy={busy} onToggle={toggleUser} onEdit={openAssignment} onNew={(item) => openAssignment(undefined, item)} />}
        {tab === "acessos" && <AccessPanel modules={modules} selectedModule={selectedModule} setSelectedModule={setSelectedModule} currentModule={currentModule} accessRows={filteredAccessRows} totalRows={effectiveAccessRows.length} />}
        {tab === "modulos" && <ModulePanel modules={modules} form={moduleForm} setForm={setModuleForm} busy={busy} onSubmit={saveModule} onEdit={(item) => setModuleForm({ id: item.id, label: item.label, description: item.description || "", icon_name: item.icon_name || "ShieldCheck", status_label: item.status_label || "Disponível", sort_order: String(item.sort_order || 0), is_ready: item.is_ready !== false })} accessRows={effectiveAccessRows} />}
        {tab === "atribuicoes" && <AssignmentPanel users={activeUsers} units={units} roles={roles} modules={modules} views={assignmentViews} form={assignmentForm} setForm={setAssignmentForm} busy={busy} onSubmit={saveAssignment} onNew={() => { setAssignmentForm(emptyAssignment()); setSelectedAssignmentId(""); }} onEnd={endAssignment} selectedId={selectedAssignmentId} setSelectedId={setSelectedAssignmentId} scopeForm={scopeForm} setScopeForm={setScopeForm} onScopeSubmit={saveScope} onScopeDelete={deleteScope} />}
        {tab === "convites" && <InvitePanel inviteForm={inviteForm} setInviteForm={setInviteForm} roles={roles} units={units} modules={modules} busy={busy} onSubmit={submitInvite} pendingInvites={pendingInvites} onReview={reviewInvite} />}
        {tab === "unidades" && <UnitPanel units={units} form={unitForm} setForm={setUnitForm} busy={busy} onSubmit={submitUnit} onReset={resetUnitForm} unitImpacts={unitImpacts} currentImpact={currentUnitImpact} />}
        {tab === "auditoria" && <AuditPanel audits={audits} search={auditSearch} setSearch={setAuditSearch} />}
      </section>}</main><footer className="health-footer"><span><ShieldCheck size={14} /> Políticas e autorização no Supabase</span><span>Governança municipal · fonte de verdade operacional</span><button type="button" onClick={onLogout}>Sair da conta</button></footer></div>;
}

function Metric({ icon: Icon, value, label, tone }: { icon: typeof Users; value: number; label: string; tone: string }) { return <div className={`governance-metric governance-metric--${tone}`}><span><Icon size={17} /></span><strong>{value}</strong><small>{label}</small></div>; }
function PanelHead({ title, description, search, setSearch, action }: { title: string; description: string; search?: string; setSearch?: (value: string) => void; action?: React.ReactNode }) { return <div className="governance-panel-head"><div><span className="section-kicker">Gestão institucional</span><h2>{title}</h2><p>{description}</p></div><div className="governance-panel-head-actions">{setSearch && <label className="governance-search"><Search size={15} /><input value={search || ""} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar" /></label>}{action}</div></div>; }
function Empty({ text }: { text: string }) { return <div className="governance-empty governance-empty--small"><ClipboardList size={20} /> {text}</div>; }
function SummaryPanel({ users, units, invites, audits, assignmentViews, summary, onTab }: { users: UserRow[]; units: Unit[]; invites: Invite[]; audits: AuditRow[]; assignmentViews: AssignmentView[]; summary: { usersWithoutAssignment: number; assignmentsWithoutModules: number; invalidAssignments: number; validityAlerts: number }; onTab: (tab: Tab) => void }) { const recentAlerts = assignmentViews.filter((view) => view.issues.length).slice(0, 5); return <section><PanelHead title="Resumo de integridade" description="A autorização efetiva depende de usuário ativo, atribuição vigente, papel, unidade, módulo e escopo aplicáveis." /><div className="governance-summary-grid"><button type="button" onClick={() => onTab("usuarios")}><UserRoundX size={20} /><strong>{summary.usersWithoutAssignment}</strong><span>usuários ativos sem atribuição vigente</span><small>Ver diretório e consistências</small></button><button type="button" onClick={() => onTab("atribuicoes")}><ClipboardList size={20} /><strong>{summary.assignmentsWithoutModules}</strong><span>atribuições sem módulos</span><small>Gerenciar atribuições</small></button><button type="button" onClick={() => onTab("atribuicoes")}><AlertTriangle size={20} /><strong>{summary.invalidAssignments}</strong><span>atribuições com inconsistência</span><small>Papel, unidade, módulo ou usuário</small></button><button type="button" onClick={() => onTab("convites")}><MailPlus size={20} /><strong>{invites.length}</strong><span>solicitações pendentes</span><small>Revisar convites</small></button></div><div className="governance-integrity-grid"><div><div className="governance-subheading"><h3>Alertas de vigência e domínio</h3><span>{summary.validityAlerts}</span></div><div className="governance-alert-list">{recentAlerts.map((view) => <article key={view.assignment.id || `${view.user.user_id}-${view.assignment.role_id}`}><div><strong>{view.user.name || view.user.email}</strong><small>{view.role?.label || view.assignment.role_label || "Papel não encontrado"} · {view.unit?.name || view.assignment.org_unit_name || "Unidade não encontrada"}</small></div><span className={`governance-pill ${statusClass(view.status)}`}>{view.status}</span><small>{view.issues.slice(0, 2).join(" · ")}</small></article>)}{recentAlerts.length === 0 && <Empty text="Nenhum alerta de consistência encontrado." />}</div></div><div className="governance-integrity-side"><div><span>Usuários monitorados</span><strong>{users.filter((item) => item.ativo !== false).length}</strong></div><div><span>Unidades ativas</span><strong>{units.filter((item) => item.is_active).length}</strong></div><div><span>Eventos recentes</span><strong>{audits.length}</strong></div></div></div><div className="governance-summary-note"><ShieldCheck size={18} /><div><strong>Fonte de verdade protegida</strong><p>Esta tela exibe e administra a autorização derivada das atribuições organizacionais. A tabela legada não participa de novas concessões.</p></div></div></section>; }
function UserDirectoryPanel({ users, assignmentViews, search, setSearch, busy, onToggle, onEdit, onNew }: { users: UserRow[]; assignmentViews: AssignmentView[]; search: string; setSearch: (value: string) => void; busy: boolean; onToggle: (item: UserRow) => Promise<void>; onEdit: (assignment: Assignment, user: UserRow) => void; onNew: (user: UserRow) => void }) { return <section><PanelHead title="Diretório de usuários" description="A identidade e o perfil legado são referências. Gerencie o acesso pela atribuição organizacional vigente." search={search} setSearch={setSearch} /><div className="governance-table-wrap"><table className="governance-table governance-users-table"><thead><tr><th>Identidade</th><th>Perfil legado</th><th>Atribuições organizacionais</th><th>Vigência e escopo</th><th>Estado</th><th>Ações</th></tr></thead><tbody>{users.map((item) => { const views = assignmentViews.filter((view) => view.user.user_id === item.user_id); return <tr key={item.user_id}><td><strong>{item.name || "Nome não informado"}</strong><small>{item.email}</small><small>{item.convite_aceito_em ? `Convite aceito em ${dateLabel(item.convite_aceito_em)}` : item.convite_enviado_em ? `Convite enviado em ${dateLabel(item.convite_enviado_em)}` : "Sem convite registrado"}</small></td><td><span className="governance-pill governance-pill--gray">{item.perfil_legacy || "Apenas referência"}</span></td><td><div className="governance-assignment-list">{views.map((view) => <div className="governance-assignment-item" key={view.assignment.id || `${view.assignment.role_id}-${view.assignment.org_unit_id}`}><strong>{view.role?.label || view.assignment.role_label || "Papel não encontrado"}</strong><small>{view.unit?.name || view.assignment.org_unit_name || "Unidade não encontrada"}</small><small>{view.modules.map((module) => module.label).join(", ") || "Nenhum módulo vinculado"}</small><span className={`governance-pill ${statusClass(view.status)}`}>{view.status}</span><div className="governance-inline-actions"><button type="button" onClick={() => onEdit(view.assignment, item)}><Edit3 size={13} /> Editar</button><button type="button" onClick={() => onNew(item)}><Plus size={13} /> Nova</button></div></div>)}{views.length === 0 && <small className="governance-muted">Sem atribuições cadastradas.</small>}<button type="button" className="governance-link-button" onClick={() => onNew(item)}><Plus size={13} /> Gerenciar atribuições</button></div></td><td><div className="governance-assignment-list">{views.map((view) => <div key={view.assignment.id || `${view.assignment.role_id}-validity`}><small>{validityLabel(view.assignment)}</small><small>{view.scopes.length ? view.scopes.map(scopeLabel).join(", ") : "Escopo global (sem restrição cadastrada)"}</small>{view.issues.length > 0 && <small className="governance-consistency-warning">{view.issues.join(" · ")}</small>}</div>)}</div></td><td><span className={`governance-pill ${item.ativo === false ? "governance-pill--red" : "governance-pill--green"}`}>{item.ativo === false ? "Inativo" : "Ativo"}</span></td><td><button className="governance-icon-button" type="button" onClick={() => void onToggle(item)} disabled={busy} title={item.ativo === false ? "Reativar usuário" : "Desativar usuário"} aria-label={item.ativo === false ? "Reativar usuário" : "Desativar usuário"}>{item.ativo === false ? <UserRoundCheck size={15} /> : <UserRoundX size={15} />}</button></td></tr>; })}</tbody></table>{users.length === 0 && <Empty text="Nenhum usuário encontrado." />}</div></section>; }
function AccessPanel({ modules, selectedModule, setSelectedModule, currentModule, accessRows, totalRows }: { modules: ModuleRow[]; selectedModule: string; setSelectedModule: (value: string) => void; currentModule?: ModuleRow; accessRows: AccessRow[]; totalRows: number }) { return <section><PanelHead title="Acessos efetivos por atribuição" description="Somente combinações vigentes de usuário, atribuição, papel, unidade e módulo são exibidas." /><div className="governance-access-toolbar"><label>Módulo<select value={selectedModule} onChange={(event) => setSelectedModule(event.target.value)}><option value="">Todos os módulos</option>{modules.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label>{currentModule && <span className="governance-module-context"><strong>{currentModule.label}</strong><small>{currentModule.description || currentModule.status_label || "Módulo municipal"}</small></span>}<span className="governance-access-count"><strong>{accessRows.length}</strong><small>de {totalRows} acesso(s) efetivo(s)</small></span></div><div className="governance-access-grid">{accessRows.map((item, index) => <article className="governance-access-card" key={`${item.assignment.id || "assignment"}-${item.module.id}-${index}`}><div><strong>{item.user.name || item.user.email}</strong><small>{item.user.email}</small></div><dl><div><dt>Módulo</dt><dd>{item.module.label}</dd></div><div><dt>Papel</dt><dd>{item.role?.label || item.assignment.role_label || "—"}</dd></div><div><dt>Unidade</dt><dd>{item.unit?.name || item.assignment.org_unit_name || "—"}</dd></div><div><dt>Vigência</dt><dd>{validityLabel(item.assignment)}</dd></div><div><dt>Escopo</dt><dd>{item.scopes.length ? item.scopes.map(scopeLabel).join(", ") : "Não definido"}</dd></div></dl><span className="governance-pill governance-pill--green">Origem: atribuição organizacional</span></article>)}{accessRows.length === 0 && <Empty text={selectedModule ? "Nenhum acesso efetivo para este módulo." : "Nenhum acesso efetivo derivado de atribuições vigentes."} />}</div></section>; }
function ModulePanel({ modules, form, setForm, busy, onSubmit, onEdit, accessRows }: { modules: ModuleRow[]; form: ModuleForm; setForm: (form: ModuleForm) => void; busy: boolean; onSubmit: (event: FormEvent) => void; onEdit: (item: ModuleRow) => void; accessRows: AccessRow[] }) { return <section><PanelHead title="Catálogo de módulos" description="Cadastre os módulos disponíveis para as atribuições. Alterações de disponibilidade podem interromper acessos efetivos." action={<button className="governance-primary" type="button" onClick={() => setForm(emptyModule())}><Plus size={14} /> Novo módulo</button>} /><div className="governance-two-column"><form className="governance-editor" onSubmit={onSubmit}><div className="governance-editor-title"><Settings2 size={17} /> {form.id ? "Editar módulo" : "Novo módulo"}</div><div className="governance-form-grid"><label>Identificador técnico<input value={form.id} onChange={(event) => setForm({ ...form, id: event.target.value })} required disabled={Boolean(modules.some((item) => item.id === form.id))} /><small className="governance-field-help">Use o identificador estável consumido pelo módulo.</small></label><label>Nome exibido<input value={form.label} onChange={(event) => setForm({ ...form, label: event.target.value })} required /></label><label>Ícone<input value={form.icon_name} onChange={(event) => setForm({ ...form, icon_name: event.target.value })} /></label><label>Status<input value={form.status_label} onChange={(event) => setForm({ ...form, status_label: event.target.value })} /></label><label>Ordem<input type="number" value={form.sort_order} onChange={(event) => setForm({ ...form, sort_order: event.target.value })} /></label><label className="governance-checkbox"><input type="checkbox" checked={form.is_ready} onChange={(event) => setForm({ ...form, is_ready: event.target.checked })} /> Disponível para novas atribuições</label><label className="governance-form-wide">Descrição<textarea value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} /></label></div><div className="governance-form-actions"><button type="submit" className="governance-primary" disabled={busy}><Check size={15} /> Salvar módulo</button></div></form><div className="governance-card-list">{modules.map((item) => { const impact = accessRows.filter((access) => access.module.id === item.id).length; return <article className="governance-list-card" key={item.id}><div><strong>{item.label}</strong><small>{item.id} · {item.description || item.status_label || "Sem descrição"}</small><small>{impact} acesso(s) efetivo(s)</small></div><div className="governance-inline-actions"><span className={`governance-pill ${item.is_ready === false ? "governance-pill--amber" : "governance-pill--green"}`}>{item.is_ready === false ? "Indisponível" : "Disponível"}</span><button type="button" onClick={() => onEdit(item)}><Edit3 size={13} /> Editar</button></div></article>; })}{modules.length === 0 && <Empty text="Nenhum módulo cadastrado." />}</div></div></section>; }
function AssignmentPanel({ users, units, roles, modules, views, form, setForm, busy, onSubmit, onNew, onEnd, selectedId, setSelectedId, scopeForm, setScopeForm, onScopeSubmit, onScopeDelete }: { users: UserRow[]; units: Unit[]; roles: Role[]; modules: ModuleRow[]; views: AssignmentView[]; form: AssignmentForm; setForm: (form: AssignmentForm) => void; busy: boolean; onSubmit: (event: FormEvent) => void; onNew: () => void; onEnd: (view: AssignmentView) => Promise<void>; selectedId: string; setSelectedId: (value: string) => void; scopeForm: ScopeForm; setScopeForm: (form: ScopeForm) => void; onScopeSubmit: (event: FormEvent) => void; onScopeDelete: (scope: ScopeRow) => Promise<void> }) { const selectedView = views.find((view) => view.assignment.id === selectedId); const availableScopes = selectedId ? views.find((view) => view.assignment.id === selectedId)?.scopes || [] : []; return <section><PanelHead title="Atribuições organizacionais" description="Conceda acesso por usuário, papel, unidade, módulos, vigência e escopo. A alteração não grava permissões diretas legadas." action={<button className="governance-primary" type="button" onClick={onNew}><Plus size={14} /> Nova atribuição</button>} /><div className="governance-two-column"><form className="governance-editor" onSubmit={onSubmit}><div className="governance-editor-title"><Edit3 size={17} /> {form.id ? "Editar atribuição" : "Nova atribuição"}</div><div className="governance-form-grid"><label>Usuário<select value={form.user_id} onChange={(event) => setForm({ ...form, user_id: event.target.value })} required><option value="">Selecione</option>{users.map((item) => <option key={item.user_id} value={item.user_id}>{item.name || item.email} · {item.email}</option>)}</select></label><label>Papel organizacional<select value={form.role_id} onChange={(event) => setForm({ ...form, role_id: event.target.value })} required><option value="">Selecione</option>{roles.filter((item) => item.is_active).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><label>Unidade organizacional<select value={form.org_unit_id} onChange={(event) => setForm({ ...form, org_unit_id: event.target.value })} required><option value="">Selecione</option>{units.filter((item) => item.is_active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Módulos da atribuição<select multiple value={form.module_ids} onChange={(event) => setForm({ ...form, module_ids: Array.from(event.target.selectedOptions, (option) => option.value) })} required>{modules.filter((item) => item.is_ready !== false).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select><small className="governance-field-help">Ctrl/Cmd seleciona múltiplos módulos.</small></label><label>Início da vigência<input type="date" value={form.valid_from} onChange={(event) => setForm({ ...form, valid_from: event.target.value })} required /></label><label>Fim da vigência<input type="date" value={form.valid_until} min={form.valid_from} onChange={(event) => setForm({ ...form, valid_until: event.target.value })} /></label><label className="governance-checkbox"><input type="checkbox" checked={form.active} onChange={(event) => setForm({ ...form, active: event.target.checked })} /> Atribuição ativa</label><label className="governance-form-wide">Justificativa administrativa<textarea value={form.justification} onChange={(event) => setForm({ ...form, justification: event.target.value })} placeholder="Informe o motivo da concessão ou alteração." /></label></div><div className="governance-form-actions"><button type="button" onClick={onNew}>Limpar</button><button type="submit" className="governance-primary" disabled={busy}><Check size={15} /> Salvar atribuição</button>{selectedView && <button type="button" onClick={() => void onEnd(selectedView)} disabled={busy}><Trash2 size={14} /> Encerrar</button>}</div></form><div><div className="governance-subheading"><h3>Atribuições cadastradas</h3><span>{views.length}</span></div><div className="governance-card-list">{views.map((view) => <article className={`governance-list-card ${selectedId === view.assignment.id ? "governance-list-card--selected" : ""}`} key={view.assignment.id}><div><strong>{view.user.name || view.user.email}</strong><small>{view.role?.label || view.assignment.role_label || "Papel não encontrado"} · {view.unit?.name || view.assignment.org_unit_name || "Unidade não encontrada"}</small><small>{view.modules.map((module) => module.label).join(", ") || "Sem módulos"} · {validityLabel(view.assignment)}</small></div><div className="governance-inline-actions"><span className={`governance-pill ${statusClass(view.status)}`}>{view.status}</span><button type="button" onClick={() => { setSelectedId(view.assignment.id || ""); setScopeForm({ ...scopeForm, assignment_id: view.assignment.id || "" }); setForm({ id: view.assignment.id || "", user_id: String(view.user.user_id), org_unit_id: view.assignment.org_unit_id || "", role_id: view.assignment.role_id || "", module_ids: moduleIds(view.assignment.module_ids), active: view.assignment.active !== false, valid_from: view.assignment.valid_from || todayISO(), valid_until: view.assignment.valid_until || "", justification: "" }); }}><Edit3 size={13} /> Editar</button></div></article>)}{views.length === 0 && <Empty text="Nenhuma atribuição cadastrada." />}</div></div></div>{selectedId && <div className="governance-scope-editor"><div className="governance-editor-title"><ShieldCheck size={17} /> Escopos da atribuição selecionada</div><form className="governance-form-grid" onSubmit={onScopeSubmit}><label>Tipo de escopo<select value={scopeForm.scope_type} onChange={(event) => setScopeForm({ ...scopeForm, scope_type: event.target.value })}><option value="ORG_UNIT">Unidade organizacional</option><option value="SECRETARIAT">Secretaria</option><option value="MODULE">Módulo</option><option value="CUSTOM">Personalizado</option></select></label><label>Chave do escopo<input value={scopeForm.scope_key} onChange={(event) => setScopeForm({ ...scopeForm, scope_key: event.target.value })} placeholder="Código ou identificador oficial" /></label><div className="governance-form-actions"><button className="governance-primary" type="submit" disabled={busy}><Plus size={14} /> Adicionar escopo</button></div></form><div className="governance-scope-list">{availableScopes.map((scope) => <div className="governance-list-card" key={`${scope.scope_type}-${scope.scope_key}`}><span>{scopeLabel(scope)}</span><button type="button" className="governance-icon-button" onClick={() => void onScopeDelete(scope)} disabled={busy} title="Remover escopo" aria-label="Remover escopo"><Trash2 size={14} /></button></div>)}{availableScopes.length === 0 && <small className="governance-muted">Nenhum escopo cadastrado para esta atribuição.</small>}</div></div>}</section>; }
function InvitePanel({ inviteForm, setInviteForm, roles, units, modules, busy, onSubmit, pendingInvites, onReview }: { inviteForm: { nome: string; email: string; perfil_municipal: string; role_id: string; org_unit_id: string; module_ids: string[] }; setInviteForm: (value: { nome: string; email: string; perfil_municipal: string; role_id: string; org_unit_id: string; module_ids: string[] }) => void; roles: Role[]; units: Unit[]; modules: ModuleRow[]; busy: boolean; onSubmit: (event: FormEvent) => void; pendingInvites: Invite[]; onReview: (item: Invite, decision: "approve" | "reject") => Promise<void> }) { return <section><PanelHead title="Convites e solicitações" description="Cada convite cria uma atribuição organizacional completa." /><div className="governance-two-column"><form className="governance-editor" onSubmit={onSubmit}><div className="governance-editor-title"><MailPlus size={17} /> Novo convite</div><div className="governance-form-grid"><label>Nome completo<input value={inviteForm.nome} onChange={(event) => setInviteForm({ ...inviteForm, nome: event.target.value })} required /></label><label>E-mail institucional<input type="email" value={inviteForm.email} onChange={(event) => setInviteForm({ ...inviteForm, email: event.target.value })} required /></label><label>Perfil legado de referência<select value={inviteForm.perfil_municipal} onChange={(event) => setInviteForm({ ...inviteForm, perfil_municipal: event.target.value })}><option>ADMINISTRATIVO</option><option>SECRETARIO</option><option>PREFEITO</option></select></label><label>Papel organizacional<select value={inviteForm.role_id} onChange={(event) => setInviteForm({ ...inviteForm, role_id: event.target.value })} required><option value="">Selecione</option>{roles.filter((item) => item.is_active).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><label>Unidade organizacional<select value={inviteForm.org_unit_id} onChange={(event) => setInviteForm({ ...inviteForm, org_unit_id: event.target.value })} required><option value="">Selecione</option>{units.filter((item) => item.is_active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Módulos da atribuição<select multiple value={inviteForm.module_ids} onChange={(event) => setInviteForm({ ...inviteForm, module_ids: Array.from(event.target.selectedOptions, (option) => option.value) })} required>{modules.filter((item) => item.is_ready !== false).map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label></div><button className="governance-primary" type="submit" disabled={busy}><MailPlus size={15} /> Enviar convite</button></form><div><div className="governance-subheading"><h3>Solicitações pendentes</h3><span>{pendingInvites.length}</span></div><div className="governance-card-list">{pendingInvites.map((item) => <article className="governance-list-card" key={item.id}><div><strong>{item.invitee_name}</strong><small>{item.invitee_email} · {item.role_label || "Papel não informado"}</small><small>{item.org_unit_name || "Unidade não informada"} · {item.module_label || "Módulo não informado"} · solicitado em {dateLabel(item.requested_at)}</small></div><div className="governance-inline-actions"><button type="button" onClick={() => void onReview(item, "approve")} disabled={busy}><Check size={14} /> Aprovar</button><button type="button" onClick={() => void onReview(item, "reject")} disabled={busy}><X size={14} /> Rejeitar</button></div></article>)}{pendingInvites.length === 0 && <Empty text="Nenhuma solicitação pendente." />}</div></div></div></section>; }
function UnitPanel({ units, form, setForm, busy, onSubmit, onReset, unitImpacts, currentImpact }: { units: Unit[]; form: { id: string; parent_id: string; code: string; name: string; unit_type: string; description: string; sort_order: string; is_active: boolean }; setForm: (value: { id: string; parent_id: string; code: string; name: string; unit_type: string; description: string; sort_order: string; is_active: boolean }) => void; busy: boolean; onSubmit: (event: FormEvent) => void; onReset: () => void; unitImpacts: Map<string, { assignments: number; activeAssignments: number; modules: Set<string> }>; currentImpact?: { assignments: number; activeAssignments: number; modules: Set<string> } }) { return <section><PanelHead title="Unidades organizacionais" description="A estrutura hierárquica é parte da autorização. Inativações preservam o histórico." /><div className="governance-two-column"><form className="governance-editor" onSubmit={onSubmit}><div className="governance-editor-title"><Building2 size={17} /> {form.id ? "Editar unidade" : "Nova unidade"}</div>{currentImpact && <div className="governance-impact-note"><ShieldCheck size={16} /><span><strong>{currentImpact.activeAssignments} acesso(s) efetivo(s)</strong> em {currentImpact.assignments} atribuição(ões), cobrindo {currentImpact.modules.size} módulo(s).</span></div>}<div className="governance-form-grid"><label>Código<input value={form.code} onChange={(event) => setForm({ ...form, code: event.target.value })} required /></label><label>Nome<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Tipo<select value={form.unit_type} onChange={(event) => setForm({ ...form, unit_type: event.target.value })}><option>SECRETARIA</option><option>DEPARTAMENTO</option><option>UNIDADE</option><option>SETOR</option></select></label><label>Unidade superior<select value={form.parent_id} onChange={(event) => setForm({ ...form, parent_id: event.target.value })}><option value="">Nenhuma</option>{units.filter((item) => item.id !== form.id && item.is_active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Ordem<input type="number" value={form.sort_order} onChange={(event) => setForm({ ...form, sort_order: event.target.value })} /></label><label className="governance-checkbox"><input type="checkbox" checked={form.is_active} onChange={(event) => setForm({ ...form, is_active: event.target.checked })} /> Unidade ativa</label><label className="governance-form-wide">Descrição<textarea value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} /></label></div><div className="governance-form-actions"><button type="button" onClick={onReset}>Limpar</button><button className="governance-primary" type="submit" disabled={busy}><Check size={15} /> Salvar unidade</button></div></form><div className="governance-card-list">{units.map((item) => { const impact = unitImpacts.get(item.id); return <article className="governance-list-card" key={item.id}><div><strong>{item.name}</strong><small>{item.code} · {item.unit_type} · {item.description || "Sem descrição"}</small><small>{impact?.activeAssignments || 0} acesso(s) efetivo(s) · {impact?.modules.size || 0} módulo(s)</small></div><div className="governance-inline-actions"><span className={`governance-pill ${item.is_active ? "governance-pill--green" : "governance-pill--gray"}`}>{item.is_active ? "Ativa" : "Inativa"}</span><button type="button" onClick={() => setForm({ id: item.id, parent_id: item.parent_id || "", code: item.code, name: item.name, unit_type: item.unit_type, description: item.description || "", sort_order: String(item.sort_order || 0), is_active: item.is_active })}><Settings2 size={14} /> Editar</button></div></article>; })}{units.length === 0 && <Empty text="Nenhuma unidade disponível no contexto." />}</div></div></section>; }
function AuditPanel({ audits, search, setSearch }: { audits: AuditRow[]; search: string; setSearch: (value: string) => void }) { return <section><PanelHead title="Trilha de auditoria" description="Eventos de concessão, revogação, papel, unidade, escopo e vigência retornados pela RPC protegida." search={search} setSearch={setSearch} /><div className="governance-timeline">{audits.map((item) => <article key={String(item.id)}><span className="governance-timeline-dot" /><div><strong>{item.actor_name || item.ator_nome || "Ator não identificado"}</strong><span>{actionLabel(item.action || item.operacao || item.entidade)}</span><small>{item.target_name || item.target_email || "Registro institucional"} · {dateLabel(item.created_at || item.occurred_at || item.ocorrido_em)}</small><small className="governance-audit-details">{auditDetails(item.details)}</small></div></article>)}{audits.length === 0 && <Empty text="Nenhum evento de auditoria encontrado." />}</div></section>; }
